const updatePositions = () => {
  if (isStale()) return;
  const vpH = win.innerHeight || doc.documentElement.clientHeight || 600;
  const vpW = win.innerWidth || doc.documentElement.clientWidth || 800;
  for (const { video, button } of entries) {
    if (!doc.contains(video)) {
      button.style.display = 'none';
      continue;
    }
    const rect = video.getBoundingClientRect();
    if (
      rect.width === 0 ||
      rect.height === 0 ||
      rect.bottom <= 0 ||
      rect.top >= vpH ||
      rect.right <= 0 ||
      rect.left >= vpW
    ) {
      button.style.display = 'none';
      continue;
    }
    const pad = 6;
    button.style.display = 'inline-flex';
    const bRect = button.getBoundingClientRect();
    const btnHeight = Math.max(28, bRect.height || button.offsetHeight || 28);
    const btnWidth = Math.max(1, bRect.width || button.offsetWidth || 130);
    const maxTop = Math.max(pad, vpH - btnHeight - pad);
    const maxLeft = Math.max(pad, vpW - btnWidth - pad);
    const top = Math.max(pad, Math.min(rect.top + pad, maxTop));
    const left = Math.max(pad, Math.min(rect.left + pad, maxLeft));
    button.style.top = `${top}px`;
    button.style.left = `${left}px`;
  }
};

updatePositions();

win.addEventListener('scroll', updatePositions, { passive: true, capture: true });
win.addEventListener('resize', updatePositions, { passive: true });

let ro: ResizeObserver | null = null;
if (typeof ResizeObserver !== 'undefined') {
  ro = new ResizeObserver(() => updatePositions());
  for (const { video } of entries) {
    ro.observe(video);
  }
}

